import{_ as t,o as e,c as s,a5 as n}from"./chunks/framework.C1a7WKBV.js";const u=JSON.parse('{"title":"Prompt 提示词秘籍","description":"把需求说清楚的套路——结构化模板、约束示例、先方案后实现与审查修复循环。","frontmatter":{"title":"Prompt 提示词秘籍","description":"把需求说清楚的套路——结构化模板、约束示例、先方案后实现与审查修复循环。"},"headers":[],"relativePath":"tips/prompt-secrets.md","filePath":"tips/prompt-secrets.md","lastUpdated":1788838685000}'),i={name:"tips/prompt-secrets.md"};function l(o,a,p,r,h,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="prompt-提示词秘籍" tabindex="-1">Prompt 提示词秘籍 <a class="header-anchor" href="#prompt-提示词秘籍" aria-label="Permalink to &quot;Prompt 提示词秘籍&quot;">​</a></h1><p>同样的模型，提示词不同，产出天差地别。差别不在辞藻，而在是否把&quot;任务、约束、参照、验收&quot;说清楚。</p><p>本篇面向<strong>编程与交付场景</strong>。日常聊天场景的入门动作（任务、上下文、示例、角色），先看《<a href="/concepts/prompt-basics">提示词入门</a>》。</p><h2 id="_1-让-ai-一次生成更准的四个要素" tabindex="-1">1. 让 AI 一次生成更准的四个要素 <a class="header-anchor" href="#_1-让-ai-一次生成更准的四个要素" aria-label="Permalink to &quot;1. 让 AI 一次生成更准的四个要素&quot;">​</a></h2><h3 id="_1-1-任务-说清做什么" tabindex="-1">1.1 任务：说清做什么 <a class="header-anchor" href="#_1-1-任务-说清做什么" aria-label="Permalink to &quot;1.1 任务：说清做什么&quot;">​</a></h3><p>用动词开头，一句话说清动作和对象。&quot;帮我优化代码&quot;是坏提示词；&quot;把 <code>formatDate</code> 函数改成支持时区参数&quot;是好提示词。</p><h3 id="_1-2-约束-说清边界" tabindex="-1">1.2 约束：说清边界 <a class="header-anchor" href="#_1-2-约束-说清边界" aria-label="Permalink to &quot;1.2 约束：说清边界&quot;">​</a></h3><ul><li>技术约束：只用现有依赖、不引入新库。</li><li>兼容约束：保持函数签名不变、不能破坏现有调用。</li><li>范围约束：只改指定文件，不要顺手重构别处。</li></ul><p>AI 很爱&quot;顺手多做&quot;，明确写出&quot;只改 X，其他不动&quot;能省掉大量回退。</p><h3 id="_1-3-参照-给示例或模板" tabindex="-1">1.3 参照：给示例或模板 <a class="header-anchor" href="#_1-3-参照-给示例或模板" aria-label="Permalink to &quot;1.3 参照：给示例或模板&quot;">​</a></h3><p>&quot;参考 <code>getUser</code> 的写法&quot;比十句描述都有效。让 AI 模仿项目里已有的好代码，是最快的对齐方式。</p><h3 id="_1-4-验收-说清怎么算完成" tabindex="-1">1.4 验收：说清怎么算完成 <a class="header-anchor" href="#_1-4-验收-说清怎么算完成" aria-label="Permalink to &quot;1.4 验收：说清怎么算完成&quot;">​</a></h3><p>写明验证命令（构建、测试、lint），并要求 AI 完成后自己跑一遍。AI 自己验证过的交付，质量明显高于&quot;写完就交&quot;。</p><h2 id="_2-结构化需求模板" tabindex="-1">2. 结构化需求模板 <a class="header-anchor" href="#_2-结构化需求模板" aria-label="Permalink to &quot;2. 结构化需求模板&quot;">​</a></h2><p>复杂需求直接套这个模板：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：一句话说清最终效果</span></span>
<span class="line"><span>背景：相关的业务或技术背景，两三句即可</span></span>
<span class="line"><span>涉及文件：明确列出或让 AI 先搜索定位</span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 约束一（技术/兼容/范围）</span></span>
<span class="line"><span>2. 约束二</span></span>
<span class="line"><span>3. 参照物：参考 XX 的实现风格</span></span>
<span class="line"><span>验收：完成后运行 XXX 命令，必须通过</span></span></code></pre></div><p>简单任务不必全套照搬，但&quot;目标 + 约束 + 验收&quot;三样始终值得写。</p><h2 id="_3-先方案-后实现" tabindex="-1">3. 先方案，后实现 <a class="header-anchor" href="#_3-先方案-后实现" aria-label="Permalink to &quot;3. 先方案，后实现&quot;">​</a></h2><h3 id="_3-1-为什么要两步走" tabindex="-1">3.1 为什么要两步走 <a class="header-anchor" href="#_3-1-为什么要两步走" aria-label="Permalink to &quot;3.1 为什么要两步走&quot;">​</a></h3><p>直接说&quot;实现它&quot;，AI 会把构思和编码挤在一次输出里，方案缺陷被代码细节淹没。两步走把&quot;想清楚&quot;和&quot;做出来&quot;解耦。</p><h3 id="_3-2-标准话术" tabindex="-1">3.2 标准话术 <a class="header-anchor" href="#_3-2-标准话术" aria-label="Permalink to &quot;3.2 标准话术&quot;">​</a></h3><p>第一步：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先不要写代码。给出实现方案：要改哪些文件、新增哪些函数、</span></span>
<span class="line"><span>有没有风险点。等我确认后再动手。</span></span></code></pre></div><p>第二步：审完方案，提出修改意见，然后说&quot;按这个方案实现&quot;。</p><h3 id="_3-3-追问让方案更扎实" tabindex="-1">3.3 追问让方案更扎实 <a class="header-anchor" href="#_3-3-追问让方案更扎实" aria-label="Permalink to &quot;3.3 追问让方案更扎实&quot;">​</a></h3><ul><li>&quot;这个方案对现有调用方有什么影响？&quot;</li><li>&quot;有没有更简单的做法？&quot;</li><li>&quot;边界情况怎么处理？&quot;</li></ul><h2 id="_4-审查与修复循环" tabindex="-1">4. 审查与修复循环 <a class="header-anchor" href="#_4-审查与修复循环" aria-label="Permalink to &quot;4. 审查与修复循环&quot;">​</a></h2><h3 id="_4-1-收到代码后的审查清单" tabindex="-1">4.1 收到代码后的审查清单 <a class="header-anchor" href="#_4-1-收到代码后的审查清单" aria-label="Permalink to &quot;4.1 收到代码后的审查清单&quot;">​</a></h3><ul><li>diff 是否只包含要求内的改动。</li><li>错误处理是否覆盖（网络、空值、越界）。</li><li>命名与风格是否符合项目惯例。</li><li>有没有硬编码的值、临时的 console.log。</li></ul><h3 id="_4-2-高效的修复提示词" tabindex="-1">4.2 高效的修复提示词 <a class="header-anchor" href="#_4-2-高效的修复提示词" aria-label="Permalink to &quot;4.2 高效的修复提示词&quot;">​</a></h3><p>报错时把<strong>完整报错信息 + 复现步骤</strong>给 AI，比转述有效得多：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行 npm run build 报错如下（完整粘贴）：</span></span>
<span class="line"><span>XXX</span></span>
<span class="line"><span>我做了哪些操作：XXX</span></span>
<span class="line"><span>先分析根因，不要急着改代码。</span></span></code></pre></div><p>&quot;先分析根因，不要急着改&quot;这句话能阻止 AI 头痛医头地乱打补丁。</p><h3 id="_4-3-让-ai-自查" tabindex="-1">4.3 让 AI 自查 <a class="header-anchor" href="#_4-3-让-ai-自查" aria-label="Permalink to &quot;4.3 让 AI 自查&quot;">​</a></h3><p>交付前让 AI 用一段固定话术自查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查你刚才的改动：有没有多余改动、遗漏的边界情况、</span></span>
<span class="line"><span>未使用的导入。发现问题直接修复。</span></span></code></pre></div><h2 id="_5-常见的坏习惯" tabindex="-1">5. 常见的坏习惯 <a class="header-anchor" href="#_5-常见的坏习惯" aria-label="Permalink to &quot;5. 常见的坏习惯&quot;">​</a></h2><ul><li>一句话甩需求，让 AI 猜：&quot;帮我做个登录。&quot;</li><li>贴整屏代码而不是让它自己搜索定位。</li><li>报错只说&quot;跑不起来&quot;，不贴原始信息。</li><li>连续追加需求在同一会话，上下文越滚越乱。</li><li>生成后不审查直接合并。</li></ul><p>对照这份清单改掉一条，产出质量立刻能上一个台阶。</p><p>相关阅读：《<a href="/tips/ai-coding-principles">通用 AI 编程方法论</a>》（任务拆解与验证闭环）、《<a href="/tips/roadmap">从零到驾驭 AI：成长路径</a>》第一阶段（提问基本功的刻意练习）。</p>`,40)])])}const q=t(i,[["render",l]]);export{u as __pageData,q as default};
